function icon(name, cls = 'icon') {
  return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.arrow}</svg>`;
}
function esc(value = '') { return String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;'); }
function safeUrl(value, fallback = '#') {
  if (!value) return fallback;
  try { const u = new URL(value, location.origin); return ['http:','https:','mailto:','tel:'].includes(u.protocol) ? u.href : fallback; } catch { return fallback; }
}
function titleCase(value = '') { return String(value).replaceAll('_',' ').replace(/\b\w/g, c => c.toUpperCase()); }
function dateText(value, opts = {}) {
  if (!value) return 'Time TBA';
  const d = new Date(value); if (Number.isNaN(d.getTime())) return 'Time TBA';
  return new Intl.DateTimeFormat('en-US', { timeZone: 'America/Chicago', weekday: opts.short ? 'short' : 'long', month: opts.short ? 'short' : 'long', day: 'numeric', hour: opts.noTime ? undefined : 'numeric', minute: opts.noTime ? undefined : '2-digit' }).format(d);
}
function timeText(value) { if (!value) return ''; const d = new Date(value); return new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',hour:'numeric',minute:'2-digit'}).format(d); }
function money(value) { return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(value || 0)); }
function slugify(value) { return String(value || '').toLowerCase().trim().replace(/[’']/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,70); }
function currentOrigin() { return location.origin; }
function uuid() { return crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`; }
function visitor() {
  let id = localStorage.getItem(VISITOR_KEY); if (!id) { id = uuid(); localStorage.setItem(VISITOR_KEY,id); }
  let session = sessionStorage.getItem('pourmap-session-id'); if (!session) { session = uuid(); sessionStorage.setItem('pourmap-session-id',session); }
  return { id, session };
}
function showToast(message, isError = false) {
  const el = document.querySelector('#toast'); if (!el) return;
  el.textContent = message; el.className = `toast visible${isError ? ' error' : ''}`;
  clearTimeout(showToast.timer); showToast.timer = setTimeout(() => el.className = 'toast', 3800);
}
async function copy(value) { await navigator.clipboard.writeText(value); showToast('Link copied.'); }
function navigate(path) { history.pushState({},'',path); render(); scrollTo({top:0,behavior:'instant'}); }
function routeLinks() { document.querySelectorAll('a[data-route]').forEach(a => a.addEventListener('click', e => { if (e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.target==='_blank') return; const u=new URL(a.href); if(u.origin!==location.origin)return; e.preventDefault(); navigate(u.pathname+u.search); })); }
function formValues(form) { return Object.fromEntries([...new FormData(form).entries()].map(([k,v]) => [k, typeof v === 'string' ? v.trim() : v])); }

const api = {
  headers(token, extra = {}) { return { apikey: SB_KEY, 'Content-Type':'application/json', ...(token ? {Authorization:`Bearer ${token}`} : {}), ...extra }; },
  async parse(res) { const text = await res.text(); let body = null; try { body = text ? JSON.parse(text) : null; } catch { body = text; } if(!res.ok){ const e=new Error(body?.message||body?.msg||body?.error_description||body?.error||`Request failed (${res.status}).`); e.status=res.status; throw e;} return body; },
  async rpc(name, args = {}, token = null) { return this.parse(await fetch(`${SB_URL}/rest/v1/rpc/${name}`,{method:'POST',headers:this.headers(token),body:JSON.stringify(args)})); },
  session() { try { return JSON.parse(localStorage.getItem(SESSION_KEY)||'null'); } catch { return null; } },
  saveSession(s) { if(!s) localStorage.removeItem(SESSION_KEY); else { if(!s.expires_at && s.expires_in) s.expires_at=Math.floor(Date.now()/1000)+Number(s.expires_in); localStorage.setItem(SESSION_KEY,JSON.stringify(s)); } },
  async signIn(email,password) { const s=await this.parse(await fetch(`${SB_URL}/auth/v1/token?grant_type=password`,{method:'POST',headers:this.headers(),body:JSON.stringify({email,password})})); this.saveSession(s); return s; },
  async signUp(email,password) { const s=await this.parse(await fetch(`${SB_URL}/auth/v1/signup`,{method:'POST',headers:this.headers(),body:JSON.stringify({email,password})})); if(s?.access_token)this.saveSession(s); return s; },
  async recover(email) { return this.parse(await fetch(`${SB_URL}/auth/v1/recover`,{method:'POST',headers:this.headers(),body:JSON.stringify({email,redirect_to:`${currentOrigin()}/login`})})); },
  async refresh(s) { if(!s?.refresh_token)return null; const n=await this.parse(await fetch(`${SB_URL}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:this.headers(),body:JSON.stringify({refresh_token:s.refresh_token})})); this.saveSession(n); return n; },
  async auth() { let s=this.session(); if(!s)return null; if(s.expires_at && s.expires_at*1000<Date.now()+60000){ try{s=await this.refresh(s);}catch{this.saveSession(null);return null;} } const res=await fetch(`${SB_URL}/auth/v1/user`,{headers:this.headers(s.access_token)}); if(res.status===401){this.saveSession(null);return null;} const user=await this.parse(res); return {user,session:s}; },
  logout() { this.saveSession(null); },
  publicMap(lat=DEFAULT_CENTER.latitude,lng=DEFAULT_CENTER.longitude,radius=100,query=null) { return this.rpc('pourmap_public_map',{p_latitude:lat,p_longitude:lng,p_radius_miles:radius,p_query:query||null}); },
  promoter(slug) { return this.rpc('pourmap_public_promoter',{p_slug:slug}); },
  venue(slug) { return this.rpc('pourmap_public_venue',{p_slug:slug}); },
  share(slug) { return this.rpc('pourmap_public_share',{p_share_slug:slug}); },
  activity(type, data={}) { const v=visitor(); return this.rpc('pourmap_record_activity',{p_event_type:type,p_promoter_id:data.promoter_id||null,p_venue_id:data.venue_id||null,p_shift_id:data.shift_id||null,p_campaign_id:data.campaign_id||null,p_share_post_id:data.share_post_id||null,p_session_id:v.session,p_visitor_key:v.id,p_source:data.source||document.referrer||'direct',p_medium:data.medium||'website',p_metadata:data.metadata||{}},this.session()?.access_token||null).catch(()=>null); },
  dashboard(token) { return this.rpc('pourmap_dashboard_bundle',{},token); },
  profile(token,data) { return this.rpc('pourmap_upsert_my_profile',{p_display_name:data.display_name,p_slug:data.slug||null,p_bio:data.bio||null,p_headline:data.headline||null,p_photo_url:data.photo_url||null,p_social_links:data.social_links||{},p_tip_links:data.tip_links||{},p_avatar_config:data.avatar_config||{},p_allow_private_booking:!!data.allow_private_booking,p_home_city:data.home_city||null,p_home_state:data.home_state||null},token); },
  connect(token,venueId) { return this.rpc('pourmap_request_connection',{p_venue_id:venueId},token); },
  createShift(token,data) { return this.rpc('pourmap_create_shift',{p_venue_id:data.venue_id,p_starts_at:data.starts_at,p_ends_at:data.ends_at,p_public_note:data.public_note||null},token); },
  startShift(token,id,lat=null,lng=null) { return this.rpc('pourmap_start_shift',{p_shift_id:id,p_latitude:lat,p_longitude:lng},token); },
  endShift(token,id) { return this.rpc('pourmap_end_shift',{p_shift_id:id},token); },
  createShare(token,data) { return this.rpc('pourmap_create_share',{p_campaign_id:data.campaign_id,p_shift_id:data.shift_id||null,p_channel:data.channel||'direct',p_custom_caption:data.caption||null,p_personal_photo_url:data.photo_url||null},token); },
  follow(token,type,id) { return this.rpc('pourmap_toggle_follow',{p_target_type:type,p_target_id:id},token); },
  async uploadPhoto(token,userId,file) {
    if(!file || !file.type.startsWith('image/')) throw new Error('Choose a JPG, PNG, or WebP image.');
    if(file.size>5*1024*1024) throw new Error('Image must be under 5 MB.');
    const ext=(file.name.split('.').pop()||'jpg').toLowerCase().replace(/[^a-z0-9]/g,'')||'jpg';
    const path=`users/${userId}/${Date.now()}-${Math.random().toString(36).slice(2)}.${ext}`;
    const res=await fetch(`${SB_URL}/storage/v1/object/pourmap-public/${path}`,{method:'POST',headers:{apikey:SB_KEY,Authorization:`Bearer ${token}`,'Content-Type':file.type,'x-upsert':'true'},body:file});
    await this.parse(res); return `${SB_URL}/storage/v1/object/public/pourmap-public/${path}`;
  }
};

function logo() { return `<a class="brand" href="/" data-route><span class="brand-mark"><span>PM</span></span><span><strong>PourMap</strong><small>Tonight has a map</small></span></a>`; }
function header(active='') {
  const signed=!!api.session();
  return `<header class="site-header"><div class="container header-inner">${logo()}<nav class="header-nav"><a class="${active==='map'?'active':''}" href="/" data-route>${icon('map')} Discover</a><a href="/about" data-route>How It Works</a><a href="${signed?'/dashboard':'/login'}" data-route>${icon('user')} ${signed?'Dashboard':'Bartender Login'}</a><a class="primary-link" href="${signed?'/dashboard?tab=shifts':'/login?mode=signup'}" data-route>${icon('plus')} Add Your Shift</a></nav><button class="button button--ghost mobile-menu-button" type="button" data-mobile-menu>${icon('menu')}</button></div></header>`;
}
function footer() { return `<footer class="site-footer"><div class="container"><div class="footer-grid"><div>${logo()}<p>See who's behind the bar, what's happening at the venue, and where to go tonight.</p></div><div><h3>Discover</h3><div class="footer-links"><a href="/" data-route>Live Map</a><a href="/about" data-route>How It Works</a><a href="/login?mode=signup" data-route>Join PourMap</a></div></div><div><h3>Bartenders</h3><div class="footer-links"><a href="/dashboard" data-route>Dashboard</a><a href="/login" data-route>Sign In</a><a href="/privacy" data-route>Location Privacy</a></div></div><div><h3>Legal</h3><div class="footer-links"><a href="/privacy" data-route>Privacy</a><a href="/terms" data-route>Terms</a><a href="mailto:support@blacklabel1.com">Support</a></div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} PourMap.</span><span>Built and operated by Black Label Branding LLC.</span></div></div></footer>`; }
function wireHeader() {
  routeLinks();
  document.querySelector('[data-mobile-menu]')?.addEventListener('click',()=>openModal('Menu',`<div class="list-cards"><a class="list-card" href="/" data-route>${icon('map')}<div class="list-card__main"><h3>Discover</h3><p>Open the live map.</p></div></a><a class="list-card" href="/about" data-route>${icon('users')}<div class="list-card__main"><h3>How It Works</h3><p>Learn about shifts, venues, and Promo Proof.</p></div></a><a class="list-card" href="${api.session()?'/dashboard':'/login'}" data-route>${icon('user')}<div class="list-card__main"><h3>${api.session()?'Dashboard':'Bartender Login'}</h3><p>Manage your PourMap profile.</p></div></a></div>`));
}
function openModal(title,body) { document.body.classList.add('no-scroll'); const el=document.createElement('div'); el.className='modal-backdrop'; el.innerHTML=`<div class="modal"><div class="modal__head"><h2>${esc(title)}</h2><button class="close-button" type="button">${icon('close')}</button></div><div class="modal__body">${body}</div></div>`; document.body.appendChild(el); const close=()=>{el.remove();document.body.classList.remove('no-scroll');}; el.querySelector('.close-button').onclick=close; el.addEventListener('click',e=>{if(e.target===el)close();}); routeLinks(); return {el,close}; }
function avatar(person,size='') {
  const cfg=person?.avatar_config||{}; const bg=cfg.background||'#27d7e7'; const emoji=cfg.emoji||'🍸';
  return `<span class="avatar${size?` avatar--${size}`:''}" style="background:${esc(bg)}">${person?.photo_url?`<img src="${safeUrl(person.photo_url)}" alt="${esc(person.display_name||'Bartender')}"/>`:esc(emoji)}</span>`;
}
function statusBadge(status, verified=false, preview=false) {
  if(preview)return `<span class="badge badge--preview">Preview crew</span>`;
  if(status==='pouring_now')return `<span class="badge badge--live">${verified?icon('verified'):''} Pouring now</span>`;
  if(status==='starts_soon')return `<span class="badge badge--soon">Starts soon</span>`;
  if(status==='scheduled_now')return `<span class="badge badge--warning">Scheduled now</span>`;
  return `<span class="badge">Tonight</span>`;
}
function eventCard(event,venue=null) {
  const url=event.destination_url||event.metadata?.external_ticket_url||'#';
  return `<article class="event-card"><div class="event-card__image">${event.hero_image_url?`<img src="${safeUrl(event.hero_image_url)}" alt="${esc(event.name)}"/>`:''}</div><div class="event-card__body"><span class="badge badge--soon">${icon('calendar')} ${esc(dateText(event.starts_at,{short:true}))}</span><h3>${esc(event.name)}</h3>${venue?`<p>${esc(venue.name)}</p>`:''}<p>${esc(event.description||'Live event and venue promotion.')}</p><a class="button button--gold" href="${safeUrl(url)}" target="_blank" rel="noreferrer" data-event-click data-campaign-id="${esc(event.id||'')}">${icon('ticket')} ${esc(event.call_to_action||'Event Details')}</a></div></article>`;
}

let mapView = { map:null, markers:[], data:null, selected:null, filters:new Set(), location:{...DEFAULT_CENTER}, query:'' };
async function renderMapPage() {
  document.title='PourMap — Tonight has a map';
  app.innerHTML=`${header('map')}<main class="map-shell"><section class="map-stage"><div id="map"></div><div class="map-overlay"><form class="search-panel" data-map-search><div class="search-input-wrap">${icon('search')}<input class="search-input" name="query" value="${esc(mapView.query)}" placeholder="Search bartenders, venues, towns…" autocomplete="off"/></div><button class="button button--primary" type="submit">${icon('search')}<span>Search</span></button><button class="button button--ghost" type="button" data-locate title="Use my location">${icon('locate')}<span>Near me</span></button></form><div class="filter-row">${[['now','Pouring now'],['tonight','Tonight'],['music','Live music'],['food','Food'],['tickets','Tickets'],['verified','Verified']].map(([id,label])=>`<button class="filter-chip${mapView.filters.has(id)?' active':''}" type="button" data-filter="${id}">${esc(label)}</button>`).join('')}</div></div><div class="map-status"><span class="status-dot"></span><span data-map-status>Loading live venue data…</span></div></section><aside class="discovery-panel"><div class="discovery-head"><h1>Tonight near you</h1><p>Tap a venue or bartender to see the shift, event, ordering, tickets, and directions.</p></div><div class="discovery-list" data-venue-list><div class="empty-state"><div class="spinner" style="margin:auto"></div><h3>Opening the map</h3><p>Loading nearby venues and pour crews.</p></div></div></aside></main>`;
  wireHeader();
  initMap();
  document.querySelector('[data-map-search]').addEventListener('submit',e=>{e.preventDefault();mapView.query=formValues(e.currentTarget).query||'';loadMap();});
  document.querySelector('[data-locate]').addEventListener('click',locateUser);
  document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const f=b.dataset.filter;mapView.filters.has(f)?mapView.filters.delete(f):mapView.filters.add(f);b.classList.toggle('active',mapView.filters.has(f));renderVenueList();drawMarkers();}));
  await loadMap();
  api.activity('map_view',{metadata:{query:mapView.query}});
}
function initMap() {
  if(!window.L){document.querySelector('#map').innerHTML='<div class="empty-state" style="margin:90px 20px">Map tiles could not load. Venue discovery is still available in the list.</div>';return;}
  mapView.map=L.map('map',{zoomControl:false,attributionControl:true}).setView([mapView.location.latitude,mapView.location.longitude],9);
  L.control.zoom({position:'bottomright'}).addTo(mapView.map);
  L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',{maxZoom:20,attribution:'&copy; OpenStreetMap contributors &copy; CARTO'}).addTo(mapView.map);
}
async function loadMap() {
  const status=document.querySelector('[data-map-status]'); if(status)status.textContent='Refreshing venue and shift data…';
  try { mapView.data=await api.publicMap(mapView.location.latitude,mapView.location.longitude,150,mapView.query||null); renderVenueList(); drawMarkers(); if(status)status.textContent=`${filteredVenues().length} venue${filteredVenues().length===1?'':'s'} in this view · live data`; }
  catch(e){console.error(e);if(status)status.textContent='Live data unavailable';document.querySelector('[data-venue-list]').innerHTML=`<div class="empty-state"><h3>We lost the signal</h3><p>${esc(e.message)}</p><button class="button button--primary" type="button" onclick="location.reload()">Try again</button></div>`;}
}
function filteredVenues() {
  let venues=mapView.data?.venues||[];
  return venues.filter(v=>{
    const crew=v.crew||[], events=v.events||[];
    if(mapView.filters.has('now')&&!crew.some(c=>c.status==='pouring_now'))return false;
    if(mapView.filters.has('tonight')&&!crew.length)return false;
    if(mapView.filters.has('music')&&!events.some(e=>String(e.metadata?.category||'').includes('music')))return false;
    if(mapView.filters.has('food')&&!v.order_url)return false;
    if(mapView.filters.has('tickets')&&!events.some(e=>e.call_to_action?.toLowerCase().includes('ticket')||e.metadata?.ticketing_mode==='external'))return false;
    if(mapView.filters.has('verified')&&!v.is_verified)return false;
    return true;
  });
}
function renderVenueList() {
  const host=document.querySelector('[data-venue-list]'); if(!host)return; const venues=filteredVenues();
  if(!venues.length){host.innerHTML='<div class="empty-state"><h3>No matching pours</h3><p>Clear a filter or search a nearby town.</p></div>';return;}
  host.innerHTML=venues.map(v=>{
    const crew=v.crew||[], event=v.events?.[0], live=crew.filter(c=>c.status==='pouring_now');
    return `<article class="venue-card${mapView.selected===v.id?' selected':''}" data-venue-card="${esc(v.id)}"><div class="venue-card__cover">${v.cover_image_url?`<img src="${safeUrl(v.cover_image_url)}" alt="${esc(v.name)}"/>`:''}<span class="badge venue-card__distance">${v.distance_miles!=null?`${esc(v.distance_miles)} mi`:'Local'}</span></div><div class="venue-card__body"><div class="venue-card__title"><div><h2>${esc(v.name)} ${v.is_verified?`<span title="Verified venue" style="color:var(--cyan)">${icon('verified')}</span>`:''}</h2><div class="venue-card__location">${esc([v.city,v.state].filter(Boolean).join(', '))}</div></div>${live.length?'<span class="badge badge--live">Live</span>':''}</div>${crew.length?`<div class="crew-stack">${crew.slice(0,4).map(c=>avatar(c,'small')).join('')}<div class="crew-label"><strong>${esc(crew.slice(0,3).map(c=>c.display_name).join(', '))}${crew.length>3?` +${crew.length-3}`:''}</strong><span>${live.length?`${live.length} pouring now`:`${crew.length} working tonight`}</span></div></div>`:'<p style="color:var(--muted);font-size:.8rem">Roster coming soon.</p>'}${event?`<div class="venue-card__event"><strong>${esc(event.name)}</strong><span>${esc(dateText(event.starts_at,{short:true}))}</span></div>`:''}<div class="venue-card__actions"><a class="button button--small button--primary" href="/venue/${encodeURIComponent(v.slug)}" data-route>Open Venue</a><a class="button button--small button--ghost" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent([v.address_line1,v.city,v.state,v.postal_code].filter(Boolean).join(', '))}" target="_blank" rel="noreferrer" data-directions data-venue-id="${esc(v.id)}">${icon('pin')} Directions</a></div></div></article>`;
  }).join('');
  host.querySelectorAll('[data-venue-card]').forEach(card=>card.addEventListener('mouseenter',()=>selectVenue(card.dataset.venueCard,false)));
  host.querySelectorAll('[data-venue-card]').forEach(card=>card.addEventListener('click',e=>{if(e.target.closest('a,button'))return;selectVenue(card.dataset.venueCard,true);}));
  host.querySelectorAll('[data-directions]').forEach(a=>a.addEventListener('click',()=>api.activity('directions',{venue_id:a.dataset.venueId})));
  routeLinks();
}
function drawMarkers() {
  if(!mapView.map)return; mapView.markers.forEach(m=>m.remove()); mapView.markers=[];
  const venues=filteredVenues(); const bounds=[];
  venues.forEach(v=>{
    const crew=v.crew||[]; const live=crew.some(c=>c.status==='pouring_now');
    const avatars=crew.slice(0,3).map(c=>{const cfg=c.avatar_config||{};return `<span class="venue-pin__avatar" style="background:${esc(cfg.background||'#27d7e7')}">${esc(cfg.emoji||'🍸')}</span>`;}).join('')||'<span class="venue-pin__avatar" style="background:#ffd166">🍺</span>';
    const html=`<div class="venue-pin">${live?'<span class="venue-pin__pulse"></span>':''}<div class="venue-pin__bubble"><div class="venue-pin__crew">${avatars}</div></div>${crew.length>3?`<span class="venue-pin__count">+${crew.length-3}</span>`:''}</div>`;
    const marker=L.marker([v.latitude,v.longitude],{icon:L.divIcon({className:'',html,iconSize:[72,72],iconAnchor:[36,65]})}).addTo(mapView.map).on('click',()=>{selectVenue(v.id,true);api.activity('pin_tap',{venue_id:v.id});});
    mapView.markers.push(marker);bounds.push([v.latitude,v.longitude]);
  });
  if(bounds.length===1)mapView.map.setView(bounds[0],12); else if(bounds.length>1)mapView.map.fitBounds(bounds,{padding:[70,70],maxZoom:13});
}
function selectVenue(id,pan) {
  mapView.selected=id; const v=(mapView.data?.venues||[]).find(x=>x.id===id); if(!v)return;
  document.querySelectorAll('[data-venue-card]').forEach(c=>c.classList.toggle('selected',c.dataset.venueCard===id));
  const card=document.querySelector(`[data-venue-card="${CSS.escape(id)}"]`); card?.scrollIntoView({behavior:'smooth',block:'nearest'});
  if(pan&&mapView.map)mapView.map.flyTo([v.latitude,v.longitude],13,{duration:.7});
}
function locateUser() {
  if(!navigator.geolocation){showToast('Location is not available in this browser.',true);return;}
  const b=document.querySelector('[data-locate]'); b.disabled=true;
  navigator.geolocation.getCurrentPosition(pos=>{mapView.location={latitude:pos.coords.latitude,longitude:pos.coords.longitude};mapView.map?.flyTo([pos.coords.latitude,pos.coords.longitude],11);loadMap().finally(()=>b.disabled=false);},()=>{showToast('Location permission was not granted. You can still search by town.',true);b.disabled=false;},{enableHighAccuracy:false,timeout:9000,maximumAge:300000});
}

function detailHeader(title,copyText,image,badges='',actions='') { return `<section class="page-hero">${image?`<img class="page-hero__image" src="${safeUrl(image)}" alt="${esc(title)}"/>`:''}<div class="page-hero__inner">${badges}<h1>${esc(title)}</h1>${copyText?`<p>${esc(copyText)}</p>`:''}${actions?`<div class="button-row" style="margin-top:20px">${actions}</div>`:''}</div></section>`; }
