async function followTarget(type,id) { const auth=await api.auth(); if(!auth){showToast('Sign in to follow bartenders and venues.');navigate(`/login?next=${encodeURIComponent(location.pathname)}`);return;} try{const r=await api.follow(auth.session.access_token,type,id);showToast(r.following?'Followed. You will be able to receive updates.':'Unfollowed.');api.activity(r.following?'follow':'unfollow',{[type==='venue'?'venue_id':'promoter_id']:id});}catch(e){showToast(e.message,true);} }
