function renderAuthPage() {
  const params=new URLSearchParams(location.search); const initial=params.get('mode')==='signup'?'signup':'login'; document.title='Bartender Login | PourMap';
  app.innerHTML=`${header()}<main class="auth-page"><section class="auth-visual"><div class="auth-visual__copy"><span class="badge badge--live">Bartender access</span><h1>Put your next shift on the map.</h1><p>Create your portable profile, connect to venues, publish shifts, grab approved promotions, and see the customers your links actually drive.</p></div></section><section class="auth-form-wrap"><div class="auth-card"><h2>Welcome to PourMap</h2><p>Bartenders join free. Venues control official promotions; Promo Proof handles attribution.</p><div class="auth-tabs"><button class="${initial==='login'?'active':''}" type="button" data-auth-tab="login">Sign In</button><button class="${initial==='signup'?'active':''}" type="button" data-auth-tab="signup">Create Account</button></div><form data-auth-form data-mode="${initial}"><div class="field"><label>Email</label><input name="email" type="email" required autocomplete="email"/></div><div class="field" style="margin-top:12px"><label>Password</label><input name="password" type="password" minlength="6" required autocomplete="current-password"/></div><button class="button button--primary" type="submit" style="width:100%;margin-top:16px">${initial==='login'?'Sign In':'Create Free Account'} ${icon('arrow')}</button><button class="button button--ghost" type="button" data-recover style="width:100%;margin-top:8px">Send Password Reset</button><p class="form-status" role="status"></p></form></div></section></main>`;
  wireHeader();
  document.querySelectorAll('[data-auth-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-auth-tab]').forEach(x=>x.classList.toggle('active',x===b));const f=document.querySelector('[data-auth-form]');f.dataset.mode=b.dataset.authTab;f.querySelector('button[type=submit]').innerHTML=`${b.dataset.authTab==='login'?'Sign In':'Create Free Account'} ${icon('arrow')}`;}));
  const form=document.querySelector('[data-auth-form]'); form.addEventListener('submit',async e=>{e.preventDefault();const v=formValues(form),status=form.querySelector('.form-status'),button=form.querySelector('button[type=submit]');button.disabled=true;status.textContent=form.dataset.mode==='login'?'Signing in…':'Creating account…';status.className='form-status';try{const result=form.dataset.mode==='login'?await api.signIn(v.email,v.password):await api.signUp(v.email,v.password);if(form.dataset.mode==='signup'&&!result?.access_token){status.textContent='Account created. Check your email to confirm it, then sign in.';status.className='form-status success';button.disabled=false;return;}const next=params.get('next')||'/dashboard';navigate(next);}catch(err){status.textContent=err.message;status.className='form-status error';button.disabled=false;}});
  document.querySelector('[data-recover]').addEventListener('click',async()=>{const email=form.email.value.trim(),status=form.querySelector('.form-status');if(!email){status.textContent='Enter your email address first.';status.className='form-status error';return;}try{await api.recover(email);status.textContent='Password reset sent. Check your email.';status.className='form-status success';}catch(e){status.textContent=e.message;status.className='form-status error';}});
}

let dashboardState={auth:null,data:null,tab:'overview',photoFile:null,photoUrl:null,avatarEmoji:'🍸',avatarBg:'#ff3d96',avatarAccent:'#ffd166'};
